// ═══ src/types.ts ═══
export interface HandlerOptions {
  priority: number;
  id: string;
}

export type Middleware<T = any> = (
  event: string,
  payload: T,
  next: () => Promise<void>
) => Promise<void>;

export interface RegisteredHandler {
  callback: (data: any) => void | Promise<void>;
  priority: number;
  pattern: RegExp;
  isWildcard: boolean;
  id: string;
}

export type EventMap = Record<string, any>;

export interface ILogger {
  log(msg: string): void;
  error(msg: string, err?: any): void;
}

// ═══ src/WildcardMatcher.ts ═══
export class WildcardMatcher {
  /**
   * Converts a dot-separated pattern into a RegExp.
   * '*' matches a single segment.
   * '**' matches one or more segments.
   */
  static toRegex(pattern: string): RegExp {
    const escaped = pattern
      .split('.')
      .map((segment) => {
        if (segment === '**') return '.+';
        if (segment === '*') return '[^.]+';
        // Escape special regex characters in literal segments
        return segment.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      })
      .join('\\.');
    return new RegExp(`^${escaped}$`);
  }
}

// ═══ src/EventBus.ts ═══
import { 
  EventMap, 
  HandlerOptions, 
  ILogger, 
  Middleware, 
  RegisteredHandler 
} from './types';
import { WildcardMatcher } from './WildcardMatcher';

export class EventBus<T extends EventMap> {
  private handlers: Map<string, RegisteredHandler[]> = new Map();
  private middleware: Middleware[] = [];
  private activeEmits: Set<keyof T | string> = new Set();
  private logger?: ILogger;

  constructor(options?: { logger?: ILogger }) {
    this.logger = options?.logger;
  }

  public subscribe<K extends keyof T | string>(
    pattern: K,
    handler: (data: any) => void | Promise<void>,
    options: HandlerOptions
  ): void {
    const patternStr = pattern as string;
    const isWildcard = patternStr.includes('*');
    const registered: RegisteredHandler = {
      callback: handler,
      priority: options.priority,
      pattern: WildcardMatcher.toRegex(patternStr),
      isWildcard,
      id: options.id
    };

    if (!this.handlers.has(patternStr)) {
      this.handlers.set(patternStr, []);
    }

    const list = this.handlers.get(patternStr)!;
    list.push(registered);
    // Sort DESC by priority
    list.sort((a, b) => b.priority - a.priority);
  }

  public use(mw: Middleware): void {
    this.middleware.push(mw);
  }

  public async emit<K extends keyof T>(event: K, data: T[K]): Promise<void> {
    const eventName = event as string;

    // 1. Circularity check
    if (this.activeEmits.has(eventName)) {
      throw new Error(`Circular emission detected for event: ${eventName}`);
    }

    this.activeEmits.add(eventName);

    try {
      // 2. Identify matches across all registered patterns
      const matchedHandlers: RegisteredHandler[] = [];
      for (const [pattern, handlers] of this.handlers.entries()) {
        // Since we store the pre-compiled regex in each RegisteredHandler, 
        // we can just check the first one in the list for that pattern key.
        if (handlers.length > 0 && handlers[0].pattern.test(eventName)) {
          matchedHandlers.push(...handlers);
        }
      }

      // 3. Flatten and sort by priority
      matchedHandlers.sort((a, b) => b.priority - a.priority);

      // 4. Build and execute middleware chain
      const executeHandlers = async () => {
        for (const handler of matchedHandlers) {
          try {
            await Promise.resolve(handler.callback(data));
          } catch (error) {
            if (eventName !== 'bus.error') {
              // Prevent infinite recursion by checking event name
              await this.emit('bus.error' as any, { event: eventName, error, data });
            } else {
              this.logger?.error('Error in bus.error handler', error);
            }
          }
        }
      };

      const chain = this.middleware.reduceRight(
        (next, mw) => async () => await mw(eventName, data, next),
        executeHandlers
      );

      await chain();
    } finally {
      this.activeEmits.delete(eventName);
    }
  }
}

// ═══ src/decorators/Retry.ts ═══
export function Retry(options: { attempts: number; delayMs: number; backoff: boolean }) {
  return function (target: any, propertyKey: string, descriptor: PropertyDescriptor) {
    const originalMethod = descriptor.value;

    descriptor.value = async function (...args: any[]) {
      let lastError: any;

      for (let i = 0; i < options.attempts; i++) {
        try {
          return await originalMethod.apply(this, args);
        } catch (err) {
          lastError = err;
          if (i < options.attempts - 1) {
            const delay = options.backoff 
              ? options.delayMs * (i + 1) 
              : options.delayMs;

            await new Promise((resolve) => setTimeout(resolve, delay));
          }
        }
      }

      throw lastError;
    };

    return descriptor;
  };
}

// ═══ tests/EventBus.test.ts ═══
import { EventBus } from '../src/EventBus';
import { Retry } from '../src/decorators/Retry';

async function runTests() {
  console.log('Starting EventBus Tests...');

  // 1. Priority Test
  const bus = new EventBus<any>();
  const executionOrder: number[] = [];

  bus.subscribe('test.priority', () => executionOrder.push(1), { priority: 1, id: 'low' });
  bus.subscribe('test.priority', () => executionOrder.push(10), { priority: 10, id: 'high' });

  await bus.emit('test.priority', {});
  console.assert(JSON.stringify(executionOrder) === '[10,1]', 'Priority order failed');

  // 2. Wildcard Test
  const wildcardMatches: string[] = [];
  bus.subscribe('system.*', (d) => wildcardMatches.push('single'), { priority: 5, id: 's' });
  bus.subscribe('system.**', (d) => wildcardMatches.push('multi'), { priority: 5, id: 'm' });

  await bus.emit('system.login', {});
  console.assert(wildcardMatches.includes('single') && wildcardMatches.includes('multi'), 'Wildcard matching failed');

  wildcardMatches.length = 0;
  await bus.emit('system.auth.login', {});
  console.assert(!wildcardMatches.includes('single') && wildcardMatches.includes('multi'), 'Deep wildcard matching failed');

  // 3. Middleware Test
  const busWithMw = new EventBus<{ log: { msg: string, ts?: number } }>();
  busWithMw.use(async (event, payload, next) => {
    if (event === 'log') payload.ts = Date.now();
    await next();
  });

  let capturedTs = 0;
  busWithMw.subscribe('log', (p) => { capturedTs = p.ts; }, { priority: 1, id: 'l' });
  await busWithMw.emit('log', { msg: 'hello' });
  console.assert(capturedTs > 0, 'Middleware enrichment failed');

  // 4. Error Handling & bus.error
  const errorBus = new EventBus<any>();
  let errorHandled = false;
  errorBus.subscribe('fail', () => { throw new Error('Boom'); }, { priority: 1, id: 'f' });
  errorBus.subscribe('bus.error', (err) => {
    if (err.event === 'fail') errorHandled = true;
  }, { priority: 1, id: 'err-h' });

  await errorBus.emit('fail', {});
  console.assert(errorHandled === true, 'Internal bus.error emission failed');

  // 5. Retry Decorator Test
  class TestService {
    public calls = 0;
    @Retry({ attempts: 3, delayMs: 10, backoff: false })
    async failingMethod() {
      this.calls++;
      if (this.calls < 3) throw new Error('Retry me');
      return 'success';
    }
  }

  const service = new TestService();
  const result = await service.failingMethod();
  console.assert(result === 'success' && service.calls === 3, 'Retry decorator failed');

  console.log('All tests passed!');
}

runTests().catch(console.error);
